    "notes": "The King of Dragons is a 1991 Capcom arcade beat-'em-up released on CPS1 hardware. Players pick from character classes including Fighter, Cleric, and Wizard, each leveling up and gaining new abilities as they fight through a fantasy world of orcs, lizardmen, and dragons. This B-Board 89625B-1 revision differs notably from the earlier World version: the Cleric starts with 40 HP instead of 48, the first extra life arrives at 200,000 points rather than 100,000, fruit restores only 12 HP, and new foes like green lizard spearmen appear. It uses a single 4-Mbit EPROM instead of four 1-Mbit chips."
