    "notes": "Vampire Savior 2 - The Lord of Vampire is a 1997 Capcom fighting game on CPS-II hardware, where fifteen characters battle to end Jedah's reign and save their souls. It hit Japanese arcades in September 1997 as the 26th CPS2 title, supporting two players with an 8-way joystick and six buttons each. The intro hides a split-second montage of character sketches. Donovan's inclusion stems from a Capcom change: the original Vampire Savior draft had him turned into a demon and Anita added as a teen, but both were cut and only restored, ageless, here. The game isn't canon, partly due to Pyron, destroyed in the first tournament."
