    "notes": "Sonic Wings 2 is a vertically scrolling shoot-em-up released by Video System on July 18, 1994, and known outside Japan as Aero Fighters 2. Players pick from eight fighter pilots, each flying a distinct jet such as the F-117A Nighthawk or the Rafale, battling jets, boats, helicopters, gun emplacements, and huge bosses whose identities change between playthroughs. Story and endings shift based on the pilot pair selected, with 47 endings in total, and the game famously blocks the initials 'SEX' on the high score table, changing them to 'OH!'. It runs on Neo-Geo MVS hardware under game ID NGM-075."
