    "notes": "Fatal Fury Special is an SNK Neo-Geo MVS fighting game from 1993, known in Japan as Garou Densetsu Special. It builds on Fatal Fury 2 with two-plane backgrounds, tighter controls, and plenty of secrets. Duck King, Tung Fu Rue, Geese Howard, and Ryo Sakazaki join the roster. The combo system was refined, damage reduced, and game speed increased. A limited soundtrack album arrived via Pony Canyon on 21/10/1993."
