    "notes": "Neo Drift Out - New Technology is an overhead isometric rally racer from Visco, released on SNK's Neo-Geo MVS in 1996. You choose between the Mitsubishi Lancer, Subaru Impreza or Toyota Celica, each with its own balance of Speed, Control and Body. After a short practice stage, up to six race stages await, each with unique locations and driving conditions. You must reach the finish before the timer runs out, hitting a mid-way checkpoint along the way. Arrows warn of corners, prompts flag hazards like ice, rocks, barrels, cones and ramps, and rival drivers can ram you into a spin. It hit Japanese arcades on March 28, 1996."
