    "notes": "Samurai Shodown IV: Amakusa's Revenge is the fourth entry in SNK's weapons-based one-on-one fighting series, released on October 25, 1996 on the Neo-Geo MVS. It features seventeen selectable characters and two end bosses. The formula changed with the removal of aerial blocking, the switch-around move, dodges, and POW gauge charging. A new CD combo was added, along with a suicide move that forfeits a round but grants a full POW gauge next round, plus certain fatalities. Older characters like Charlotte, Tam Tam, and Jubei Yagyu returned."
