    "notes": "A one-on-one fighting game released in July 2003 by Playmore on SNK Neo-Geo MVS hardware, SVC Chaos - SNK Vs. Capcom pits seventeen well-known SNK combatants against seventeen famous Capcom characters. It mainly uses the command system of the King of Fighters series, with light and strong kicks and punches, cancels and charging attacks, and unlike Capcom vs. SNK 2 it has no air guards and no groove system, focusing instead on quicker play and online competition. Each character has a basic three-bar system for executing Exceeds, filled by strikes and damage, and the sprites from the various series received new models while some command-list special effects changed."
