    "notes": "Soccer Brawl is a futuristic soccer game released by SNK in February 1992 for the Neo-Geo MVS arcade hardware. Two players face off using four buttons each, with two in use: attack with a kick or power shot, and pass, while defence offers a sliding cut or arm punch and a header. It runs on SNK's Neo-Geo MVS platform under game ID NGM-031."
