    "notes": "Miracle Adventure, known outside Japan as Spinmaster, is a platformer released by Data East on December 16, 1993, and the company's first game developed for the SNK Neo-Geo MVS hardware. Two treasure seekers, Johnny and Tom, must save their friend Mary from the evil Mad Doctor and his henchmen while gathering map pieces to find the world's biggest treasure. The game features cartoon-like character designs, giant bosses such as a Chinese dragon, and fast platforming, with a style heavily inspired by Data East's Caveman Ninja. It runs under game ID NGM-062 with three buttons: shoot or power attack, jump, and super attack."
