    "notes": "SNK's 1997 Neo-Geo MVS fighter lets you build teams of three from nine squads plus two solo entries, bringing the roster to 29 fighters. The goal is to defeat the evil Orochi and those tainted by his blood. Yuri's Hien Rekkou special is a nod to Ken's Shoryuu Reppa, and the Kowloon backdrop hides cameos from Top Hunter and Art of Fighting 3. The names of Kyo, Iori and Chizuru echo the legend of the Great Serpent."
