    "notes": "The King of Fighters 2000 is SNK's Neo-Geo MVS fighting game released in July 2000, featuring 34 characters and the popular Striker assist system. Teams battle to defeat the mighty Zero and his bladed coat. Ramon was designed with South American audiences in mind, a masked Lucha Libre wrestler full of tricky body slams. Vanessa was conceived as a thirty-something woman who broke the mold of teenage female fighters, having first appeared as a Striker in the Dreamcast version of KOF '99 before officially joining KOF 2000 as a playable character."
