    "notes": "The King of Fighters 2003 is an SNK Playmore Neo-Geo MVS fighting game released in November 2003. It offers 32 selectable fighters plus Evil Kusanagi, Chizuru and Maki Kagura, Adelheid Bernstein, and final boss Mukai. It was the latest entry in the series to run on Neo-Geo MVS hardware. Two new systems debut: the Tactical Leader System, which gives one team member favorable treatment in capability, and Multi-Shift, which lets players change characters freely during 3-on-3 battle. Ash Crimson was designed with the intent to create an attractive evil character."
