    "notes": "Thrash Rally is a top-down rally racing game from Alpha Denshi, released on November 8, 1991 for the Neo-Geo MVS. One or two players choose from vehicles with differing handling, acceleration, endurance, and top speed. World Rally Championship mode offers six rally cars across lap-based circuits with time limits. Paris-to-Dakar mode is a point-to-point race that also includes a buggy, motorbike, and truck. Tracks feature varied surfaces plus jumps, chicanes, and obstacles to avoid."
