    "notes": "Top Hunter: Roddy & Cathy is a horizontally-scrolling beat-em-up released by SNK on May 18, 1994 for the Neo-Geo MVS. One or two players control Roddy and Cathy, bounty hunters tasked with stopping the Klaptons, galactic pirates threatening the cosmos. Players jump between foreground and background planes, and can extend their arms to grab items and enemies, or pull themselves onto ledges. The game borrows special moves from SNK fighting games like Fatal Fury and Art of Fighting, including Ko'ouken and shoryuken-style attacks. Pony Canyon/Scitron released a limited-edition soundtrack on July 21, 1994."
