    "notes": "Flying Power Disc is a 1994 Data East Corp flying disc arcade game on SNK Neo-Geo MVS hardware, released February 17, 1994 in Japan and known elsewhere as Windjammers. Two players use an 8-way joystick and two buttons to slide, receive, throw, and lob. Each character speaks their own native language, and two mini-games appear: Dog Distance after match two and Flying Disc Bowling after match four. The game draws on the real sport 10-S, created in 1977 and copyrighted in 1980, without permission. On the USA territory dip switch, Korea's B. Yoo is swapped for Britain's S. Miller, keeping the same sprites but an English voice."
