    "notes": "Operation Ragnarok is a side-scrolling shoot-'em-up for one or two players on SNK's Neo-Geo MVS hardware, released by NMK in 1994. Players pick from three ships with different speeds, then configure front, rear, and projectile weapons such as Homing Missiles. Destroyed enemies and waves sometimes drop bonuses, weapon power-ups, and Hyper-Bombs, powerful smart bombs. Known as Zed Blade outside Japan, it hit Japanese arcades in September 1994 and never appeared on the Neo-Geo AES console. The high-score table refuses the initials 'AAA', changing them to 'YOU'."
