    "notes": "Ryuuko no Ken is a martial arts fighting game released by SNK Corp in 1992 on Neo-Geo MVS hardware. One-player mode offers 2 selectable characters, while two-player mode offers 8, and a long-nosed boss awaits at the end. Progressive damage appears on each fighter's face. Launched in Japan in September 1992, its title translates as 'Dragon and Tiger Fist' and it is known overseas as Art of Fighting. It was SNK's second fighting-game franchise and the first fighting game to use a camera zoom and a spirit meter, with character designs by former SNK illustrator Shinkiro. Game ID: NGM-044."
