    "notes": "Captain America and the Avengers is a 1991 Data East side-scrolling beat-'em-up with occasional shoot-'em-up sections. Players pick Captain America, Iron Man, Vision, or Hawkeye, each with a distinct weapon — shield, repulsor rays, solar beam, or bow and arrows — and allies like Quicksilver, Sub-Mariner, Wonder Man, and The Wasp appear to help. Foes include Klaw, The Living Laser, Whirlwind, The Grim Reaper, The Wizard, The Controllers, The Mandarin, The Juggernaut, Ultron, and Crossbones across five stages. Released in October 1991, it runs on Data East ARM6 hardware. Josh Bycer set the official record with 496,801 points on April 20, 1997."
