    "notes": "A fortune teller warns Billy and Jimmy Lee of a rising enemy in Egypt, and the brothers set out on a worldwide quest for the Rosetta Stone, picking up new allies along the way. This third and final arcade entry in the Double Dragon series swapped out the earlier gameplay and graphics for a new system, adding moves like the belly-to-back throw and back-to-back hurricane kick while dropping the hair grab and elbow punch. It was developed by East Technology rather than Technos' internal team, and supports up to three players, with the third controlling Sonny, a yellow-clad Lee brother unique to this game."
