    "notes": "After his defeat in the original Double Dragon, Black Warriors leader Willy strikes back by murdering Billy and Jimmy Lee's friend Marian, sending the brothers on a quest for revenge. The sequel keeps the original's attacks and combos while adding new moves like the invincible Cyclone Kick, plus redesigned stages, weapons and traps such as a bulldozer in Mission 3. Released in December 1988, the game swapped the usual punch and kick buttons for left and right attack controls. It began as a chip upgrade of the first game before growing into new hardware, and the coin-insert yell comes from the stick-wielding Mission 3 boss Chin Taimei."
