    "notes": "Flicky is a side-scrolling platform arcade game from Sega. Players control a flightless bird who must gather her scattered chicks, called chirps, and lead them to the exit door bearing her name. Cats emerging from cat-flaps roam the stages; contact costs a life, and any chick touched by a cat must be retrieved again. Each round is cleared by bringing all chirps to the exit. The first two rounds have six chirps, later rounds eight. Bonus rounds let Flicky catch falling chirps in a net for a Perfect bonus. The game was developed under the names Busty and Flipp before becoming Flicky, and released in May 1984 in Japan."
