    "notes": "Garou: Mark of the Wolves is a one-on-one fighting game and the ninth entry in SNK's Fatal Fury series, released for the Neo-Geo MVS in November 1999. Set ten years after Geese Howard's death in a peaceful Second Southtown, it features 12 characters and drops the plane-switching battles of its predecessors for standard single-plane combat. The game introduced the Tactical Offense Position, a zone on the life gauge that grants a T.O.P. attack, gradual life recovery, and increased damage, plus the Just Defend system rewarding last-moment blocks. 'Garou' translates from Japanese as 'Hungry Wolf'."
