    "notes": "Samurai Spirits, known outside Japan as Samurai Shodown, is a 1993 SNK Neo-Geo MVS weapons-based fighter with 12 characters, bonus rounds, and one end boss. Four buttons shift between armed and unarmed attacks. Released in Japan in July 1993, it pioneered weapon fighting in the genre using an upgraded scaling engine from Art of Fighting. Many characters draw on history, including Haohmaru, inspired by Miyamoto Musashi."
