    "notes": "Shin Samurai Spirits - Hahmaru Jigokuhen is a one-on-one fighting game from SNK, released in October 1994 on the Neo-Geo MVS. Fifteen weapon-wielding combatants battle to earn the right to face a powerful and difficult end boss. Building on the first game, SNK added characters and moves, including the POW meter for super specials that can break an opponent's weapon. It also introduced rolling, ducking, small hops, and the first offensive blocking technique, the parry. The game is known outside Japan as Samurai Shodown II."
