    "notes": "Segasonic The Hedgehog is a scrolling isometric racing game released by Sega, supporting one to three players as Sonic, Ray, and Mighty escape Eggman Island after Dr. Robotnik imprisons them in a tower. Gameplay keeps series staples like jumping on enemies and collecting golden rings, while levels are filled with lava flows, collapsible platforms, and locked gates. Though the title screen reads 1992, the game actually launched in Japan in September 1993, and it marked the first appearance of Ray and Mighty. It runs on Sega's System 32 hardware with a trackball and one button per player."
