    "notes": "Snow Bros. - Nick & Tom is a single-screen platform arcade game from Toaplan, released in April 1990. One or two players control snowmen Nick and Tom, throwing snowballs to encase enemies and then kicking the giant snowballs across the screen to destroy anything in their path. Across fifty levels, an invincible pumpkin head appears if you take too long, spawning unkillable ghosts. Defeated enemies may drop coloured potion power-ups, and the game was licensed to Romstar for USA distribution and ran on JAMMA-compatible hardware."
