    "notes": "Super Hang-On is Sega's 1987 checkpoint-based racing sequel to Hang-On, which arrived two years earlier. Riders steer a superbike past rival bikers and roadside obstacles, reaching each stage's checkpoint before time runs out, across courses set in Africa, Asia, America, and Europe. Sega brought in the rolling roads seen in 1986's Out Run and added a turbo button. Holding turbo pushes the bike from its 280kph top speed to 324kph, a risky boost that is often needed to meet the game's tight time limits. It launched in April 1987."
