    "notes": "Twin Hawk is an arcade export release from Taito, published in June 1989 and developed in Japan. It is the export version of Dai Senpuu. Twin Hawk supports two simultaneous players, with purple and pink planes for players 1 and 2. When a player dies, they continue at their current position, compensated by tougher larger enemies and increased dynamic difficulty. Small orange bullets are harder to see than in the Japanese version."
